/**
 * Redesigned case studies (Alfa Romeo IVI, Zingerman's, Still Here, Echoes) — content manifest.
 *
 * ALL copy, numbers, quotes, captions and alt text come from the published case studies in
 * src/data/projects.js; this file only chooses a hero collage per project, the page's nav, the
 * hero title breaks, and resolves every image to a web-weight WebP copy (public/assets/redesign/cs,
 * generated by scripts/build-redesign-media.py from the original files; the lightbox opens a larger
 * copy of the same picture). Nothing is written, generated or measured here.
 *
 * `tag` is a tiny honest label under each visual:
 *   Hi-fi screen · Prototype · Deck slide · Style guide · Wireframes · Design board · In-engine · Recording
 */
import { projects, SITE, RESUME_URL } from './projects'
import { IMG } from './redesignMedia'

export { SITE, RESUME_URL }

const P = Object.fromEntries(projects.map((p) => [p.slug, p]))

/** A resolved still: web-weight copy for the page, larger copy for the lightbox. */
export function still(src, { alt, cap, tag, tall } = {}) {
  const e = IMG[src]
  if (!e) throw new Error(`No web copy for ${src}: run scripts/build-redesign-media.py`)
  return { kind: 'img', src: e.src, full: e.full, width: e.w, height: e.h, alt: alt || cap, cap: cap || alt, tag: tag ?? tagFor(src), tall }
}

export function tagFor(src) {
  if (src.includes('/stellantis/research/') || src.endsWith('competitor-analysis.png')) return 'Deck slide'
  if (src.endsWith('style-guide.png')) return 'Style guide'
  if (src.endsWith('process-wireframes.png')) return 'Wireframes'
  if (src.includes('/stellantis/')) return 'Hi-fi screen'
  if (src.includes('/zingerman/')) return src.includes('-mobile') ? 'Prototype · mobile' : 'Prototype · desktop'
  if (src.includes('/still-here/')) return 'Hi-fi screen'
  if (src.includes('/echoes/echoes-07') || src.includes('/echoes/echoes-08')) return 'In-engine'
  if (src.includes('/echoes/')) return 'Design board'
  return undefined
}

