/** project data + the manifest, with a few derived fields */
export function getCase(slug) {
  const p = P[slug]
  const c = CASES[slug]
  if (!p || !c) return null
  return {
    ...c,
    slug,
    p,
    title: p.title,
    facts: [
      ['Role', p.role],
      ['Timeline', p.timeline],
      p.team ? ['Team', Array.isArray(p.team) ? p.team.join(' · ') : p.team] : ['Type', p.snapshot.type],
      ['Tools', Array.isArray(p.tools) ? p.tools.join(' · ') : p.tools],
    ],
  }
}
